{
  "$schema": "https://opencode.ai/config.json"
}

{
  "name": "armin-opencode-plugin",
  "private": true,
  "devDependencies": {
    "@opencode/plugin": "2.0.16",
    "@types/bun": "latest"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.31"
  }
}

{
  "name": "armin-opencode",
  "version": "0.1.2",
  "description": "ARMIN — queryable decision memory for AI coding agents. Installs the armin-engine sidecar and registers the opencode plugin.",
  "license": "Apache-2.0",
  "author": "Bastian Seifert",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bastian-seifert/armin.git"
  },
  "bin": {
    "armin": "bin/armin.js"
  },
  "main": "plugins/armin.ts",
  "exports": {
    ".": "./plugins/armin.ts",
    "./server": "./plugins/armin.ts"
  },
  "files": [
    "bin/",
    "plugins/",
    "README.md"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.0",
    "jsonc-parser": "^3.3.1"
  },
  "engines": {
    "node": ">=18",
    "opencode": ">=1.0.0"
  },
  "keywords": [
    "opencode",
    "ai-agents",
    "agent-memory",
    "llm",
    "cli"
  ]
}
